package live.linghe.privateinput;
import java.util.*;
final class PinyinMatch {
 static String canonical(String value){String text=value.toLowerCase(Locale.ROOT).replace('ü','v');return text.equals("lue")?"lve":text.equals("nue")?"nve":text;}
 private static Set<String> fullForms(String part){Set<String> result=new HashSet<>();String value=canonical(part);result.add(value);if(value.equals("lve"))result.add("lue");if(value.equals("nve"))result.add("nue");return result;}
 static boolean isFullSpelling(String input,String reading){String raw=input.toLowerCase(Locale.ROOT).replace('ü','v').replace("'","").replace(" ","");String[] parts=reading.toLowerCase(Locale.ROOT).trim().split("[ ']+");if(raw.isEmpty()||raw.length()>128||parts.length>64)return false;Set<Integer> positions=new HashSet<>();positions.add(0);for(String part:parts){if(!part.matches("[a-zü]+"))return false;Set<Integer> next=new HashSet<>();for(int position:positions)for(String form:fullForms(part))if(raw.startsWith(form,position))next.add(position+form.length());positions=next;}return positions.contains(raw.length());}
 static boolean covers(String input,String reading,int maximumAbbreviations){String raw=input.toLowerCase(Locale.ROOT).replace('ü','v').replace("'","").replace(" ","");String[] parts=reading.toLowerCase(Locale.ROOT).trim().split("[ ']+");if(raw.isEmpty()||raw.length()>96||parts.length>32)return false;Map<Integer,Integer> positions=new HashMap<>();positions.put(0,0);
  for(int index=0;index<parts.length;index++){String part=parts[index];if(part.isEmpty())return false;Set<String> full=fullForms(part);Map<Integer,Integer> next=new HashMap<>();for(Map.Entry<Integer,Integer> state:positions.entrySet()){int position=state.getKey(),abbreviations=state.getValue();if(position>=raw.length())continue;String suffix=raw.substring(position);Set<String> forms=new HashSet<>(full);forms.add(part.substring(0,1));if(part.startsWith("zh")||part.startsWith("ch")||part.startsWith("sh"))forms.add(part.substring(0,2));if(index==parts.length-1&&part.startsWith(suffix)){int cost=abbreviations+(suffix.equals(part)?0:1);if(cost<=maximumAbbreviations)next.put(raw.length(),Math.min(next.getOrDefault(raw.length(),Integer.MAX_VALUE),cost));}for(String form:forms)if(suffix.startsWith(form)){int cost=abbreviations+(full.contains(form)?0:1),end=position+form.length();if(cost<=maximumAbbreviations)next.put(end,Math.min(next.getOrDefault(end,Integer.MAX_VALUE),cost));}}positions=next;if(positions.isEmpty())return false;}
  return positions.containsKey(raw.length());
 }
}
